from pathlib import Path
import json
P=Path(__file__).resolve().parent
load=lambda f:json.loads((P/f).read_text())
x=load('model/inputs.json');m=load('model/results.json');s=load('model/sensitivities.json');h=load('history/history.json');co=load('comps/outputs.json');t=load('transaction/facts.json')
def f(v,n=2):
 if v is None:return 'n/d'
 return f'{v:,.{n}f}'.replace(',','X').replace('.',',').replace('X','.')
def tab(headers,rows):return '| '+' | '.join(headers)+' |\n|'+'|'.join(['---']*len(headers))+'|\n'+'\n'.join('| '+' | '.join(map(str,r))+' |' for r in rows)
hist=tab(['Periodo','Ventas','EBIT','NI matriz','CFO','Capex bruto','Turnaround caja','FCF después TA'],[[r['period']]+[f(r['metrics'][k]['value'],0) for k in ['revenue','ebit','net_income_parent','cfo','gross_capex','cash_turnaround','fcf_after_turnaround']] for r in h['periods']])
c=x['capital'];labels={'cashExUanRounded':'Caja ex-UAN derivada','nominalDebtAndFinanceLeasesExUan':'Deuda nominal y finance leases ex-UAN','selectedOperatingCashReserve':'Reserva operativa seleccionada','rfsHistoricalLiability':'Obligación RFS histórica','derivativeNetLiabilityAfterCollateralAndAssets':'Derivados netos después de colateral y activos','historicalIncomeTaxPayable':'Impuesto corriente devengado','historicalCashCompensationLiability':'Compensación devengada ex-UAN','historicalAccruedInterestExUan':'Interés devengado ex-UAN','environmentalLegacyReserve':'Reserva ambiental anual','utbLegacyReserve':'UTB anual','uanQuotedEquityStake':'Participación UAN cotizada','selectedUanExitTaxReserve':'Reserva fiscal UAN seleccionada','unknownPostSeptemberCapital':'Cambio de capital posterior desconocido (base0)'}
capital=tab(['Concepto','Importe'],[[labels[k],f(c[k])] for k in labels]+[['Puente neto',f(m['base']['capitalBridge'])]])
assumptions=tab(['Caso','EBITDA petróleo año1→normal año5','EBITDA adquirido año1→normal año5','WACC actual/adquirido','g','ROIC'],[[case,f(v['parent']['ebitdaYear1'],0)+' → '+f(v['parent']['ebitdaNormalizedYear5'],0),f(v['target']['ebitdaYear1'],0)+' → '+f(v['target']['ebitdaNormalizedYear5'],0),f(v['parent']['wacc']*100)+'% / '+f(v['target']['wacc']*100)+'%',f(v['parent']['g']*100)+'%',f(v['parent']['roic']*100)+'%'] for case,v in x['scenarios'].items()])
assumptions+='\n\n'+tab(['Presupuesto inicial / millones','Operaciones actuales','Adquiridas'],[[name,f(x['scenarios']['base']['parent'][key]),f(x['scenarios']['base']['target'][key])] for name,key in [('Coste corporativo o adicional','corporateCashCostYear1'),('D&A incluidas paradas','daYear1'),('Capex físico mínimo','physicalCapexYear1'),('Turnarounds de caja mínimos','turnaroundCapexYear1'),('Inversión incremental en circulante','annualWorkingCapitalInvestmentYear1')]])
modeltable='### Diez años de operaciones actuales, caso base\n\n'+tab(['Fin periodo','EBITDA','Corporativo','D&A','NOPAT','Capex total','ΔWC','FCFF'],[[r['periodEnd']]+[f(r[k]) for k in ['ebitdaBeforeTurnaroundCash','corporateCashCost','daIncludingTurnaround','nopat','grossCapitalInvestment','workingCapitalInvestment','fcff']] for r in m['base']['parent']['rows']])
modeltable+='\n\n### Diez años adquiridos, caso base\n\n'+tab(['Fin periodo','EBITDA','Coste adicional','D&A','NOPAT','Capex total','ΔWC','FCFF'],[[r['periodEnd']]+[f(r[k]) for k in ['ebitdaBeforeTurnaroundCash','corporateCashCost','daIncludingTurnaround','nopat','grossCapitalInvestment','workingCapitalInvestment','fcff']] for r in m['base']['target']['rows']])
results=tab(['Caso','EV operaciones actuales','EV adquiridas','PV sinergias netas','Residuo fracaso / acción','Residuo cierre / acción'],[[case,f(v['parent']['operatingEV']),f(v['target']['operatingEV']),f(v['synergy']['pv']),f(v['failureAfterCommonOffering']['signedResidualPerShare']),f(v['immediateClosing']['signedResidualPerShare'])] for case,v in m.items()])
results+='\n\nDenominador ilustrativo tras oferta: '+f(m['base']['failureAfterCommonOffering']['shares'],6)+' millones; tras PIPE: '+f(m['base']['immediateClosing']['shares'],6)+' millones. Son supuestos de ramas, no acciones actuales verificadas.'
sens='### Principales sensibilidades, rama de cierre base\n\n'+tab(['Variable','Valores probados','Residuo por acción'],[[name,' / '.join(f(r['value']) for r in s[name]),' / '.join(f(r['closingSignedResidualPerShare']) for r in s[name])] for name in ['parentNormalizedEbitda','targetNormalizedEbitda','operatingCashReserve','uanStakeRecoveryFraction','pipePrice','workingCapitalPurchaseAdjustment','parentTurnaroundAnnual','targetTurnaroundAnnual','financingFriction']])
inv=s['inverseJointNormalizedEbitdaUplift'];rel=s['inverseExistingCapacityCycleRecovery'];fu=s['illustrativeFundingStress']
sens+='\n\nEl inverso estricto a 48,60 requiere EBITDA normalizado de '+f(inv['parentNormalizedEbitda'])+' y '+f(inv['targetNormalizedEbitda'])+' respectivamente, elevando ambos en igual importe. En la alternativa de recuperación sobre capacidad existente, requiere '+f(rel['parentNormalizedEbitda'])+' y '+f(rel['targetNormalizedEbitda'])+'. Ninguno es una previsión única. El caso favorable de cierre pasa a '+f(s['cycleRecoveryUsingExistingCapacity'][2]['closingSignedResidualPerShare'])+' por acción con esa alternativa.\n\nLa prueba de fondos arroja fuentes ilustrativas '+f(fu['sources'])+', usos incluidos pasivos y reservas '+f(fu['usesIncludingSelectedReserves'])+' y desfase '+f(fu['shortfallBeforeUnverifiedInventoryFinancingOrInterimCash'])+' millones. No es una cifra contractual de financiación faltante.'
peers=tab(['Empresa','Cierre3nov','Capitalización indicativa','VentasQ3','NI matrizQ3','EPSdiluidoQ3'],[[r['ticker']]+[f(r[k]) for k in ['price_Nov3_USD','equity_market_value_USDm','Q3_sales_USDm','Q3_parent_net_income_USDm','Q3_diluted_EPS_USD']] for r in co['companies']])
text=(P/'report_template.md').read_text().replace('1.026 frente a 312','1.026 frente a 242')
for k,v in {'HISTORY':hist,'CAPITAL':capital,'ASSUMPTIONS':assumptions,'MODEL_TABLE':modeltable,'RESULTS':results,'SENSITIVITIES':sens,'PEERS':peers,'PRICING_URL':t['sources']['priced_offering']}.items():text=text.replace('{{'+k+'}}',v)
assert '{{' not in text
(P/'report.md').write_text(text)
print('Built report',len(text.split()),'words')
